INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','بررسی دقیق اقتصادی هزینه کاشت اسپرس با باریک تیپ در هر هکتار. این مطالعه شامل تحلیل کامل از هزینه‌های کاشت، استفاده از باریک تیپ برای بهبود بازدهی اقتصادی و کاهش هزینه‌هاست. آمار و ارقام واقعی برای کشت اسپرس با روش باریک تیپ ارائه شده تا کشاورزان بتوانند تصمیم‌گیری‌های بهتری داشته باشند.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
