INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Гӯлакӯбоки (огурц) сабаби суръати баррасӣ ва бартарии иқтисодии баланд, яке аз маҳсулоти маъмултарини зафаронӣ дар минтақаҳои гарм ва нисбатан гарм кишвар ба шумор меравад. Аммо калиди даст овардани беҳтарин натиҷа бе ҳаромбардӣ дар хароҷот, интихоби дурусти зичии нишодаст. Бисёр истеҳсолкунандагони навбурда, саволро <strong>Миқдори тоҳуккуни гӯлакӯбоки дар як гектар</strong> ро барои сабаби маҳаллӣ ё умумӣ мепурсанд, ҳол ки ҷавоби дақиқ он ба тағйирёбандаҳое мисли рақам, усули парвариш (моқирӣ ё нависабодӣ), андозаи тоҳук ва минтақаи иқлимӣ вобаста аст. Дар ин дастурмо, мо формулаҳои ҳисобкунӣ, ҷадвалҳои муқоисавӣ ва тавсияҳои амалиро барои беҳтар кардани парвариши гӯлакӯбоки бо технологияи оборӣи қатқат ва навори тиб пешниҳуд мекунем. Ин раванд на танҳо ба ҳисоб кардани тоҳук маҳдуд мешавад, балки тарҳрезии зери сохтори обро низ дар бар мегирад, то аз сарфаи манбаъҳо пешгирӣ гардад. Дарки робитаи қавии байни зичии гӯлакҳо ва ниёзи об, қадами аввал барои парвариши муваффақ дар шароити иқлимии мушкил аст.</p><h2>Асосҳои ҳисоб кардани зичӣ ва миқдори тоҳук истифодашаванда</h2><p>Барои дарки дақиқе чӣ қадар тоҳук лозим аст, бояд формулаи асосии зичиро ба назар гирифт. Зичии гӯлак дар гектар (P) баробар аст ба натиҷаи тақсим намудани масоҳати умумии замин ба масоҳати ҷудошуда барои ҳар як гӯлак. Масоҳати ҳар гӯлак аз зарби масофаи қаторӣ ба масофаи шохмонда ҳосил мешавад. Бо шинохти ин формула, метавон ҳаҷми тоҳуки лозимастро тахмин зад. бояд диққат дод, ки гӯлакӯбоки гӯлаки тоҳукчасти ченк аст ва вазни тоҳукаш одатан байни 1 то 1.5 грамм тағйир мекунад. Бинобар ин, ҳисоб кардан бо килограми тоҳук, ниёз ба донистани фоизи бирӯйиш ва вазни метрии тоҳук (1000 дона) дорад. Омили чуну сифати тоҳук, шароити нигоҳдорӣ ва чуқурии кӯрпурӣ низ ба фоизи пайдошавӣ таъсир мерасонанд ва бояд дар ҳисобҳои ибтидоӣ ба назар гирифта шаванд, то камбудии нависабод дар ниҳоят пешгирӣ гардад.</p><h3>Масофаи парвариш ва таъсири он ба тоҳуки лозим</h3><p>Нави парвариши моқирӣ (тоҳуккалорам ё тоҳукчарам) таъсири бевосита ба истифодаи тоҳук дорад. Дар парвариши моқирӣ бо тоҳукчарам, одатан 2 то 3 дона дар ҳар як ҷои нишод мекуранд, то аз зарари сархӯриҳои заминӣ ё зараррасонандагони коркӣ пешгирӣ карда шавад. Пас аз бирӯйиш, гӯлакҳои иловагӣ дар ҳар як ҷои нишод хориҷ карда мешаванд, то зичии ниҳоӣ танзим гардад. Азбаски масофаи шохмонда дар парвариши моқирӣ аз парвариши нависабодӣ камтар аст, миқдори тоҳуки истифодашудаи ибтидоӣ баландтар хоҳад буд, аммӯ хароҷоти бардоштани нависабод ва кӯрпӯрии дастӣ хориҷ мешавад. Ин усул барои боғҳои калон бо дастрасӣ ба таҷҳизоти кӯрпӯрии мувофиқ, аз ҷиҳати иқтисодӣ оқилтар аст.</p><p><figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-خیار-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر خیار در هکتار: راهنمای جامع - تصویر 1"/><figcaption>миқдори тоҳук дар гектар фармаи гӯлакӯбоки</figcaption></figure></p><h2>Намоишди амалӣ: ҷадвалҳо ва маълумоти ишора</h2><p>Барои беҳтар фаҳмидани фарқияти усулҳои гуногун, дар поён ҷадвале пешниҳуд мешавад, ки миқдори тоҳуки гӯлакӯбокиро дар гектарро дар шароити стандартии боғи хонаи обӣ ва парвариши озод муқоиса мекунад. Ин рақамҳо бар асоси рақамҳои маъмул, ки ҳақиқати майдониро инъикос мекунанд, ҳастанд ва дар сурати тағйири рақамҳо ё шароити иқлимӣ, бояд дубора ҳисоб карда шаванд. Диққат ба масофаи қаторҳо муҳим аст, зеро ин масофа бевосита ба имконияти ҳаракати таҷҳизот ва ҳавопашии байни гӯлакҳо таъсир мерасонад. Ҳамчунин, интихоби пешбанди мувофиқи парвариш метавонад ба миқдори тоҳуки лозим таъсир расонад; пешбандҳои пешакӣ тайёркардашуда, одатан ба тоҳуки камтар ниёз доранд, зеро зичии дақиқтарро фароҳам меоранд. Ин ҷадвал ҳамчун манбаи ибтидоӣ барои нақшагирии хариди тоҳук ва тарҳрезии замин истифода мешавад.</p><table><thead><tr><th>Нави парвариш</th><th>Масофаи қатор (метр)</th><th>Масофаи шохмонда (метр)</th><th>Зичии ниҳоӣ (гӯлак/гектар)</th><th>Тоҳуки истифодашудаи тахминӣ (килограмм)</th></tr></thead><tbody><tr><td>Парвариши моқирӣ (тоҳуккалорам)</td><td>1.0</td><td>0.25</td><td>33,333</td><td>80 то 90</td></tr><tr><td>Кушони бемавҷӯӣ (пашуркунӣ)</td><td>1.0</td><td>0.30</td><td>27,777</td><td>50 то 60</td></tr><tr><td>Кушони хурмашӯӣ (хурмаи сабз)</td><td>1.5</td><td>0.5</td><td>13,333</td><td>-</td></tr></tbody></table><p>Дида оемед, ки дар кушони хурмашӯӣ, шумо аз бехи мустақим истифода намекунед, балки аз хурмаҳои тайёр дар хонаки ошомеъ истифода мебаред. Бинобар ин, сатри истифодаи бех холӣ аст. Аммо агар хоҳед, ки хурмаҳоро худатон дар косаҳои кушони хурмашӯӣ партошед, бояд медонед, ки барои ҳар 1000 хурма, тақрибан 400 то 500 килограмм бех дар даст нест, балки шумораи донҳо муҳим аст. Ҳарчанд ки намудҳои навтар ва намудҳои беҳдоштшуда бошанд, метавонанд ниёз ба зичии камтар ва масоفاи бештар байни бутухоро дошта бошанд, то манъ аз партофтани сояи баргҳо ба якдигар шуда шавад. идоракунии рӯшноӣ ва ҳарорат дар хонаҳои ошомеъ низ ба рушди хурмаҳо ва дар натиҷа ба самаранокии ниҳоӣ таъсир мерасонад. Бояд дида шавад, ки дар ҳисобкуниҳои кушони хурмашӯӣ, сарфҳаҷми омодакунии хурма ва косаҳои кушони хурмашӯиро низ ба сарфҳаҷми бех илова кунед, то ки буҷети умумии кушон муайян шавад. Инчунин, сифати хурмаҳои харидашуда бояд ба таҳқиқоти дақиқ оварда расонида шавад, то ки аз якхела будани андоза ва саломатии растаниҳо боварӣ ҳосил шавад.</p><h2>Алоқамандии зичии кунҷонӣ бо системҳои обёрӣи қатқат ва нӯрипӣ</h2><p>Яке аз муҳимтарин душворҳои кушони хурма, идоракунии обёрӣ мебошад. Системаи обёрӣи қатқат ва нӯрипӣ бо сабаби дақиқии баланд дар тақсимоти об ва моддаҳои ғизоӣ, бо зичиҳои гуногун рафтори гуногун доранд. Агар зичии хурмаи шумо хеле баланд бошад (масалан, зиёда аз 25,000 набукил дар гектар), истифодаи об ва моддаҳои ғизоӣ зуд зиёд мешавад. Дар ин ҳолат, истифода аз хатҳои қатқат бо масофаи камтари қатқатнокҳо, барои таъмини расидани обёрӣ ба ҳамаи решаҳо зарур аст. Ба ибораи дигар, зичии растани мустақиман ба тарҳрезии шабакаи обёрӣ таъсир мерасонад. Дар системҳои кушон, интихоби намуди кушон (мустақим ё хурмашӯӣ) ва зичии растаниҳо нақши муайянкунаро дар ниёз ба тарҳрезии дақиқи система доранд. Шумо метавонед дар бораи <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%B2%D8%B9%D9%81%D8%B1%D8%A7%D9%86-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Маблағи бехи ҷунҷуб дар гектар</a> Барои муқоисаи намунаи кушони донӣ ва таъсири он ба сарфҳаҷмҳои собит ва тағйирёбандаи кушон омӯзед. Ин муқоиса ба деҳқонон кӯмак мекунад, ки бар асоси намуди маҳсулот ва иқлим беҳтарин моделро интихоб кунанд.</p><h3>Тағйирот дар суръати обёрӣ аз рӯи зичӣ</h3><ul><li><strong>Зичии кам (пасттар аз 15,000 набукил):</strong> Шумо метавонед аз системаи бандакаи одоҳи (типаи одоҳ) истифода баред. Фазоли бандаро барои додани об метавонад то 50 см аз буташон дур кард. Ин усул барои картоши хяра бо фосилаҳои баланд мусоид аст. Дар ин ҳолат, маблағи лӯлагузорӣ камтар аст, вале барои пешгирии хушкшавии атрофи буташон ба назорати бинӣ муҳтоҷӣ зиёд дорад.</li><li><strong>Зичии миёна (15,000 то 20,000 наботот):</strong> Беҳтарин имконият истифодаи хати қатрагир (даропича) дар ҳар як сафар аст. Бандаки одоҳ бояд бевосита дар маркази буташон бошад, то ки решаҳои рӯи хяра ба таври якхела ғизо баҳм бароянд. Ҷиҳози иҷрои бандаро барои пешгирии фишори обӣ дар наботот муҳим аст.</li><li><strong>Зичии баланд ( зиёда аз 25,000 наботот):</strong> Дар ин ҳолат, пӯшиши решаҳо дар ҳадди баланд доранд. Истифодаи системаи қатрагир бо допони (қатрагир) дар фосилаҳои кӯтоҳ (масалан 15 ё 20 см) зарур аст, то ки хати хушк боқӣ намонд. Ин зичии балод одатан дар оилҳои пешрафта бо ҳавопардашавии воқеистаро истифода мерасад.</li></ul><p>Барои ин мақсад шумо метавонед дар бораи <a href="https://navar-abyari.ir/%D8%A2%D9%85%D9%88%D8%B2%D8%B4-%D8%A7%D8%B3%D8%AA%D9%81%D8%A7%D8%AF%D9%87-%D8%A7%D8%B2-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE/">омӯзиши истифодаи бандаро</a> барои овардани нобардаи лӯлаҳои обдиҳии дуруст таҳқиқ кунед. Бандаро одоҳ бо равшан ё ним-равшан истеҳсол мешавад ва имконияти наздикии бунёди решаҳоро ба вуҷуд меорад, ки барои картоши хяра, ки решаҳои нозук дорад, хеле муҳим аст. Инчунин, шиносӣ бо намудҳо ва истифодаи лӯлаҳои баробаркунанда метавонад ба деҳқон кӯмак расонад, то аз комбинатсияи системаҳои гуногуни ободиҳии оптимизатсияшуда истифода барад. Интихоби намуди лӯла ба асоси фишор ва давомнокии система таъсир мерасонад ва бояд бар асоси барнома ва шартҳои деҳот интихоб шавад.</p><p><figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-خیار-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر خیار در هکتار: راهنمای جامع - تصویر 2"/><figcaption>миқдори бадан бар як гектар картоши хяра</figcaption></figure></p><h2>Таъсири навъҳо ва андозаи бадан ба нархи ниҳоӣ</h2><p>Бадани картоши хяра дар андозаҳои хеле гуногун пешниҳод карда мешавад. Баъзе навиҳои ғибиридӣ хеле хурду кофаканд, дар сатҳи бадони навъҳои қадимии маҳаллӣ бадони калонтарин доранд. Як нуқтаи калидӣ дар муайян кардани <strong>миқдори бадони картоши хяра бар як гектар</strong> ин аст, ки ҳамеша ба вазни бадан (вазни 1000 бадан) диққат диҳед. Мисол: агар навиҳи ғибиридӣ бо вазни 1000 бадан 800 грам дошта бошад ва дигаре 1400 грам, маънояшон он аст, ки барои расидан ба ҳамон шумораи ниҳоӣ, дар навиҳи дуюм бояд тақрибан 75 фоизи бадони бештар харидаро кунед. Фарқияти нархҳои бадони тартибдодашуда ва бадони маҳаллӣ низ бояд дар ҳисобҳои иқтисодӣ ба назар гирифта шавад. Бадони тартибдодашуда одатан устувории бештар ба низоатҳо доранд ва метавонанд дар давоми дарозмоҳӣ хурҷҳои доруро кам кунанд. Инчунин, интихоби бадан дар асоси таҳаммукунандагии навиҳо ба ободиҳии қатрагирӣ низ муҳим аст; навиҳое, ки дар нисбат ба нокомии обии кӯтоҳмоҳӣ муқовимати бештар доранд, дар шароити босухаро (кушксор) ҳосили беҳтар доранд.</p><h3>Равонамаки амалӣ барои деҳқон</h3><ol><li><strong>Сифати баданро назорат кунед:</strong> Пеш аз харидорӣ, аз таъминкунандаи бадон даъват кунед, ки фоизи намунанаврӯро таҳқиқ кунед. Аз навиҳои 95 фоиз ба боло истифода баред, то ки аз лозимагии гирифтани (бардошт) ва бозниҳоронӣ дар вақти камперики пуштошӣ пешгирӣ шавад. Бадони бо сифати паст боиси камшавии зичии ниҳоӣ ва камбуди ҳосилот мебошад.</li><li><strong>Фосилаи буташонро ҳисоб кунед:</strong> Дар заминҳои нохушшавишаву ё бо қалтипони, таъмин кунед, ки фосилаи 25 то 30 см байни буташон риоя мешавад. Картоши хяра дар охирин давраи афзоиш ба намои (саюшавӣ) зиёд лозим меорад ва зичии бештар боиси камшавии намдиҳи нисбӣ ва зиёдшавии бемаънҳои қорӣ мебошад. Навишии ҳавопардашавии воқеистаро байни наботот тавассути таниди фосилаи буташон имконпазир аст.</li><li><strong>Қуруни соҳибро дар назар гиред:</strong> Дар хоки вазнин, фосилаи байни ниҳоҳҳоро каме зиёдтар интихоб кунед, то ки решаҳо тавонанд дарун шаванд. Дар хоки шағол ва сабук, зичии каме зиёдтар иҷозат дода мешавад, ба шарте ки парвариши моеъ ба ниҳоҳҳо расад. Муайян намудани навъи хок пеш аз коррониш ва беҳтар кардани он бо паррандагон (пудр) ё компост метавонад ба қобилияти нигоҳ доштани оби хок ва парвариши ниҳоҳҳо таъсир расонад.</li></ol><p>Барои муқоиса бо маҳсулоти дигар, шумо метавонед дар бораи <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%ae%d8%b1%d8%a8%d8%b2%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори боби бодак дар як гектар + Ҷадвали зичии коррониш</a> муроҳат кунед, ки нишон медиҳад чӣ тавр як маҳсулоти решаӣ ва баргдор бо растании тезрӯӣ ба идоракунии гуногун нисбат ба хӣшӣ ниёз дорад. Бодак ҳамчун хӣшӣ ба абёриш бобонад (ғулғулӣ) ҷавоб мекунад, аммо нақши решааш фарқ дорад. Инчунин, баррасии <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b3%db%8c%d8%b1-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори боби сабузи сармоӣ дар як гектар: Омили таъсирбахш ва роҳҳои зиёд кардан</a> метавонад нигаронии ҳалли зичӣ дар ҳашамҳои бофтанӣ диҳад. Сабузи сармоӣ (сармул) маҳсулоте аст, ки дақиқӣ дар зичии коррониш мустақиман ба сифати ниҳоии бобаҳо таъсир мерасонад.</p><h2>Саволҳои машҳур (FAQ) дар бораи корронии хӣшӣ</h2><h3>1. Оё боби хииширо мустақиман дар баҳш корронидан мумкин аст ё ниҳоҳ лозим аст?</h3><p>Корронии боби хиишӣ дар баҳш махсусан дар ҳудудҳои баҳсубоқ (яхбаст) камтар маъмултар аст, аммо дар минтақаҳои гармсибиста бо асоси мувофиқ, коррониш мустақим тавсия дода мешавад. Бо вуҷуди ин, коррониши ниҳоҳҳои идорашаванда барои тартиб додани вақти ҷамъоварӣ ва сифати якяксиматар маҳсулот дастрасӣ ёфтани бештар дорад. Дар ҳар ҳол, ҳисоб кардани зичии ниҳоӣ аз як гектар, фарқияти байни корронии мустақим ва ниҳоҳ надорад; нуқтаи асосӣ, фосилаи байни ниҳоҳҳо аст. Интихоти байни ин ду усул бояд дар асоси манбаъҳои инсонӣ, тартиб додани вақти ҷамъоварӣ ва сариқимати махзаҳо сурат гирад.</p><h3>2. беҳтарин боб барои абёриш бобонад кадом аст?</h3><p>Навъҳои гибриди нав, ки ба камбудии кӯтоҳмӯҳлати об тоқат доранд ва решаҳои қавӣ доранд, барои абёриш бобонад мувофиқтаранд. Нуфузеҳоро интихоб кунед, ки пӯшиши баргони кам доранд, то намии нисбии дар дохили ниҳоҳ кам шуда, ниёз ба абёриш камтар шавад. Ин масъала мустақиман ба <strong>Миқдори боби хиишӣ дар як гектар</strong> таъсир мерасонад, зеро навузеҳои гибридӣ одатан ба зичии камтар ниёз доранд. Интихоби навузеҳое, ки ба бемориҳои зангӣ муқовимат доранд, дар шароити намии баланд зарур аст.</p><h3>3. Оё фосила дар бобонадаҳо бояд тағйир ёбад?</h3><p>Бале, агар фосилаи байни ниҳоҳҳоро аз 25 то 35 сантиметр зиёд кунед, фосилаи бобонадаҳои зери асос (дар нахши тип) ё дар қатори абёриш бобонад низ бояд танзим шавад. Одатан, ҳар ниҳоҳ бояд дақиқан дар болои як бобонада ҷойгир бошад. Агар шумо нахши типи шаффоф истифода мебаред, метавонед бо наздикӣ санҷед, ки оё об ба ҳамаи ниҳоҳҳо мерасад ё не. Танзимоти нодурусти фосилаи бобонада овардаи ҳудуди қамакчашавӣ ё намнокшавӣ мекунад, ки ба соҳмании решаҳо таъсири манфӣ мерасонад.</p><h3>4. Чӣ тавр метавонем сарфи бобро кам кунем?</h3><p>Истифодаи асоси тайёр ба ҷои боби обишуда, таъмини тоза ва якяксимат будани замин, ва истифодаи усули бобдуча (ҷуп) ба ҷои бобяктӣ барои таъмини нобиҳорнак будан. Бо вуҷуди он ки бобдуча боби бештар сарф мекунад, вале гардиши ҷамъоварӣ ва корронии такрориро бартараф мекунад. Дар даромадҳо (дарозмӯҳлат), ин усул метавонад гардиши ниҳоиро паст кунад. Беҳтар кардани нобиҳорнак бо истифодаи асосҳои гарм ва рӯшноии мувофиқ, беҳтарин роҳ барои кам кардани тафаллуъҳои боб аст.</p><p><figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-خیار-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر خیار در هکتار: راهنمای جامع - تصویر 3"/><figcaption>сурати бозорҳо барои ҳектар зироати хияр</figcaption></figure></p><h2>Хулоса ва тавсияҳои ниҳоӣ</h2><p>Таҳқиқот ва мушоҳидаҳои бамаврид нишон додаанд, ки ягон формулаи мутлақ ва собит барои <strong>миқдори бозори хияр дар ҳектар</strong> мавҷуд нест, зеро тағйирёбандаҳои техникикӣ, бозор, иқлим ва системаи обёрӣ ҳама нақши калидии доранд. Бо вуҷуди ин, риояи фосилаи стандартии 25 то 30 сантиметр байни бозорҳо ва 1 то 1.5 метр байни сатҳҳо, бо истифода аз системаи чанҷиқӣ ё навиқти, беҳтарин натиҷаро фароҳам меорад. Ин танзимот ба шумо имкон медиҳад зичии тахминӣ 25,000 то 30,000 ҳарирро дар ҳектар дошта бошед, ки дар хокҳои муътадил беҳтарин мувозинатро байни ҳаҷми истеҳсолот ва саломатии ҷунубон фароҳам меорад. Тавсия мекунем, ки пеш аз оғози ғармҳо, андозаҳои дақиқи бозорҳои худро бо вазни дونا ҳисоб кунед ва ҷадвали обёриро бар асоси зичии ниҳоӣ дубора тарҳрезӣ намоед. Ба ёд оред, ки идоракунии дақиқи решаҳои хияр таъсири мустақим дорад бар миқдори истеъмоли об ва моддаҳои ғизоӣ ва системаи навиқти алақомуде барои мушоҳида ва идоракунии ин раванд аст. Нозиркунии доимии афзоиши ҳисобҳо ва танзимотҳои обёрӣ, калиди муваффақият дар истеҳсоли хияри сифатнок бо камтарин хароҷот аст.</p><h3>Манбаъҳои иловагӣ</h3><p>Барои фаҳмиши беҳтари мавзӯъҳои алоқаманд бо идоракунии зичӣ дар дигар маҳсулотҳо, тавсия мекунем <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%ae%d8%b1%d8%a8%d8%b2%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">миқдори бозори торбока дар ҳектар + ҷадвали зичии ғарм</a> ва <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b3%db%8c%d8%b1-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">миқдори бозори сармо дар ҳектар: омилҳои таъсиррасон ва роҳҳои зиёдшавӣ</a> ро омӯзед. Инчунин дар бораи намудҳо ва истифодабарии лӯлаҳои барабӣ маълумот гиред, то беҳтарин интихро барои фазои худ анҷом диҳед. Ҳамаи инҳо ба шумо кӯмак мекунанд, ки як равиши мукаммал ва асосйобӣ дошта бошед ва ба ҷои тахмин, қарорҳои ошорпазӣ гиред.</p>','Микдори бехи хияр дар ҳектар: Раҳнамои ҷамъбастшуда барои кушодан ва оборӣ','Муваффақияти ғаллои хура ба муайян кардани дақиқи зичии ғалло вобаста аст. Миқдори бодаи хура дар ҳектар вобаста ба шаклҳо, масофа байни қаторҳо ва намуди ҷоҳаки ғалло метавонад аз 5 то 25 килограмм ё шумораи тақрибан 10,000 то 15,000 нахи хура дар як ҳектар бошад. Ин мақола рамзбарии пурра барои ҳисоб кардани зичии эҳтимолӣ ва беҳтар намудани истифодаи об бо системаҳои муосири оборӣ мебошад.','publish','closed','closed','mikdori-behi-hiyar-dar-hektar',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
