INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','Garlic Drip Irrigation: Complete Guide to Micro-Sprinkler Techniques' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Master garlic cultivation with precision drip and micro-sprinkler (tape) irrigation. Discover efficient water management strategies for optimal yield and root health in agricultural systems.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','Comprehensive Guide to Garlic Cultivation Using Drip and Micro-Sprinkler Irrigation' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар парвариши сир бо технологияи оҳеи қатқатӣ</h2>\n<p>Сир яке аз гиёҳҳои сирпоякӣ аст, ки дар саноати хӯрокию дорустӣ истифодаи бисёр дорад. Ниҳол пардохтани сир ниёз ба эҳтиёт дар вақти ниҳол, зичии мувофиқи сирпоякҳо ва идоракунии дақиқи захираҳои об дорад. Дар усулҳои анъанавӣ, оҳеи таҳияи коҳиш одатан боиси талафоти об ва бемориҳои реша дар сир мегардад. Аммо бо истифода аз <strong>оҳеи қатқатӣ</strong> ва <strong>типи нӯҳӣ</strong>, метавон ҳарорат ва намнокӣ-ро дар мадҳуди реша (Zone of Root) доимӣ нигоҳ доряд. Ин усул на танҳо боиси саривазҳо дар парҳез аз сартопи об то 30-40 дарсад мебошад, балки бо зиёд кардани ҳамвории намнокӣ, рушди якхелаи сирпоякҳо ва ба ин васл зиёд шудани бартароии дар гектарро низ бо худ меорад. Дар асл, идоракунии дақиқи намнокии зони решаӣ, асоси сифати ниҳоии сирпояк дар шароити иқлими гарм ва нимхушк аст, ки қисми зиёди боғзорҳои сири кишвар дар он ҷо воқеанд.</p>\n\n<h2>Омодагии замин ва ниҳол пардохтани сир</h2>\n<p>Пеш аз насби системаи оҳе, омодагии муҳиматҳои зербунёд хеле муҳим аст. Хунук бояд аз рӯи pH-и оптималӣ (тақрибан 6 то 7) ва дренажии мувофиқ дошта бошад. Сир ба хунакҳои лумушӣ ( Sandy Loam ) ҷавоби хуб медиҳад. Марҳилаҳои омодагӣ ва ниҳол пардохтӣ ба инҳо ишора мекунанд:</p>\n<ul>\n<li><strong>Кардан ва наққоракӣ:</strong> Барои нобуд кардани ғаштаҳои бегона ва ҳавопардонии хунак.</li>\n<li><strong>Ҷамъоварӣ ва интиқол:</strong> Истифодаи бадҳо (сирпоякҳо) бо сифати баланд, ки аз бемориҳои зангӣ озод бошад.</li>\n<li><strong>Фосилаҳои парвокӣ:</strong> Одатан фосилаи сутунҳо 25 то 30 сантиметр ва фосилаи ичҳо дар сутун 15 то 20 сантиметр танзим карда мешавад, то имконоти гузариши титҳои оҳе бошад.</li>\n</ul>\n<p>Барои иҷрои дурусти фосилаҳо, шумо метавонед аз принсипҳои умумии ченкунӣ дар гектар, ки дар мақола <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D9%85%D9%84%D9%88%D9%86-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Миқдори ҷамъоварии молав дар гектар</a> шарҳ дода шудааст, ороиш кунед; зеро дарки дақиқии мумият ва фазои парвокӣ коркард, калиди идоракунии расондани расонидан аст. Инчунин, таҳлили дақиқи зичии ниҳол пардохтӣ бо шароити маҳаллӣ, метавонад фарқияти назаррасеро дар бартароии ниҳоӣ ба вуҷуд орад. Дар ин роҳ, ба назар гирифтани омилҳои муҳитӣ ва генетикии бадҳо, илова бар муҳимияти баланд дорад. Барои огоҳии дақиқтар дар бораи ченкунии зичӣ ва таъсири он ба сифати ҳосил, омӯзиши мақолаҳои алоқаманд бо ченкунии дақиқ дар гектар зарур аст. <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D9%85%D8%A7%D8%B1%DA%86%D9%88%D8%A8%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Миқдори ҷамъоварии чоробӣ дар гектар</a> Инчунин намунаи мувофиқ барои фаҳмидани даврал истихроҷи сабзавотҳо ва растаниҳои решаӣ/ширагиранда мебошад, гарчанде ки фарқиятҳои нозуки дар ихтиёзи ғизоӣ ва обёрӣ вуҷуд дорад. Дар охир, ошноии бо ҳаҷми ҳосилоти зинҷифил дар ҳектар ба ҳамчун намунаи маҳсулоти арзиши иловагии баланд кӯмак мекунад, ки шумо ҳамчун менеҷери замин ба нақшасозии кишт назари таҳлилӣ доред.</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-سیر-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت سیر با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои кишт обёрӣ қабулӣ барномаи обёрӣ сарим</figcaption></figure>\n\n<h2>Насби системаи лентаии қабулӣ барои сарим</h2>\n<p>Лентаи қабулӣ (Tape Drip) яке аз самараноктарин усулҳо барои кишти сарим аст, зеро намаро бевосита назди решаҳо таъмин мекунад. Интихоби лентаи мувофиқ вобаста ба фосилаи байни сатҳҳо аст. Лентаҳо бо фосилаи қабулҳои 10 то 15 сантӣ барои сарим идеалӣ ҳастанд. Насби дурусти лентаҳо бояд пас аз муқаррар шудани пурраи тоҷҳо иҷро шавад, то ба решаҳо осеб нарасонад. Диққат дар ин марҳила бевосита ба якхел будани пахши об ва пешгирии басташудани қабулҳо таъсир мерасонад.</p>\n<ol>\n<li>Кашидани тартиботи дақиқ ва тоза.</li>\n<li>Каштани тоҷҳо бо чуқурии 5 то 10 сантӣ.</li>\n<li>Пӯшонидани тоҷҳо бо хок.</li>\n<li>Насби лентаи қабулӣ дар миёнаи сатҳ ё қабати сатҳ, вобаста ба усули кишт.</li>\n</ol>\n<p>Барои ошноӣ бо марҳилаҳои қадам ба қадам аз насб, хондани дастурамбарии <a href="https://navar-abyari.ir/drip-irrigation-tape-installation-steps-ariq/">Марҳилаҳои насби лентаи қабулӣ барои обёрӣ</a> фоиданок хоҳад буд. Нуқтаҳои муҳим, ба монанди фишори кории мувофиқ (1 то 3 бар) ва истифодаи تور барои пешгирии басташудани қабулҳо низ дар ин манбаъ ба таври муфассал тавзеҳ дода шудааст. Илова бар ин, ошноӣ бо <a href="https://navar-abyari.ir/tarzi-nasbi-lulayi-ob-yori-tip/">усули насби холаи обёрӣ лентаӣ</a> метавонад фоиданок бошад, зеро принсипҳои умумии насби холҳо дар ин ду усул муштарак аст ва фарқияти асосӣ танҳо дар намуди қабулҳо ва ҷойгиршавии онҳо аст. Инчунин, фаҳмидани чӣ тавр фишор ва тақсимотро дар шабакаҳои обӣ идора кардан, дархости ошноӣ бо принсипҳои ҳидроликӣ мекунад, ки дар нуқтаҳои муҳим дар интихоби лентаи обӣ пурра тавзеҳ дода шудааст.</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-سیر-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت سیر با آبیاری قطره‌ای - تصویر 2"/><figcaption>усулҳои кишт обёрӣ қабулӣ барномаи обёрӣ сарим</figcaption></figure>\n\n<h2>Вақтгузорӣ ва барномаи обёрии сарим</h2>\n<p>Идоракунии вақтии обёрӣ муҳимтарин қисм дар истифодаи қабулӣ аст. Сарим дар даврони рушди вайҷӣ (пас аз ташаккули сарим) ба намии миёна ғаёбат дорад. Дар охори фасл ва вақти ташаккули сарим, ихтиёзи обёрӣ кам мегаряд, то ки пулидани саримро пешгирӣ кунад. Дар марҳилаи охирин (хушк шудани сабагҳо) пеш аз тоҷбазории, обёрӣ қатъ мешавад. Ин тағйиротҳои тадриҷии дар дозаи об, зарурати назорати дақиқи рушди растаниро талаб мекунад.</p>\n<table border="1" cellpadding="5" cellspacing="0">\n<tr><th>Марҳилаи рушди сарим</th><th>Ихтиёзи обёрӣ</th><th>Тавзеҳот</th></tr>\n<tr><td>Аз нӯмакзанӣ то қудратамбудӣ</td><td>Миёна</td><td>Нигоҳдорӣ барои таррабии баргҳо, рутубатҳи якхела</td></tr>\n<tr><td>Ташаккули пиёз</td><td>Коҳиши аҳамматӣ</td><td>Пешгирии вазифаву баҳс, баланд бардоштани сифати дохилӣ</td></tr>\n<tr><td>Порешӣ ва пӯстӣ сабуқакҳо</td><td>Тухм кардан обёркӣ</td><td>Чанд ҳафтаи муқаддам барои пухтани пиёзҳо</td></tr>\n</table>\n<p>Беҳтарин усул истифодаи ҷустуҷӯи таррабитии хок аст. Агар аз системаҳои ҳушманд истифода баред, метавонед бо истифода аз маълумоти истгоҳҳои ҳушманд, дозаи обро мувофиқи ниёзи ғалам муайян кунед. Дар ин самт, дарёфти роҳи ҳисоб кардани доза ва масофа барои ниёзҳои ғалам хеле муҳим аст. Назорати таррабӣ дар қабати рутубатӣ, кӯтоҳӣ барои назорати сифати пиёзҳо аст.</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-سیر-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت سیر با آبیاری قطره‌ای - تصویر 3"/><figcaption>услубҳои ғалам, обёрки ғалам, барномаи обёрки сабзӣ, сиёҳбӯда</figcaption></figure>\n\n<h2>Услубҳои амалӣ ва нигоҳубини иловагӣ</h2>\n<p>Илова бар обёркӣ, парҳез (Fertigation) тавассути чачакдорӣ яке аз фоидаҳои бузурги ин система аст. Шумо метавонед нуришҳои моеъро мустақиман бо об ба решаҳо расонед. Ин амал барои ҷалби беҳтарин ҳубураҳои хӯроквор барои сиёҳбӯда, ба монанди потассий (дар марҳилаи дӯппаранда), мусоид аст. Инчунин, назорати одавузаракҳо дар системаҳои чачакдорӣ каме мураккабтар аст, зеро тарраби сатҳӣ камтар аст, аммо бо тӯби ғаламкӯши мувофиқ ва идоракунии обборӣ, идоракунаканди қобилиятаконанда аст. Истифодаи мато ё машин метавонад барои кам кардани ниёз ба ғаламкушӣ кӯмак расонад.</p>\n<p>Яке аз нуқтаҳои муҳим, пешгирии бемориҳои қарҷӣ бо таъмини ҳавокашии мувофиқ аст. Гарчанде ки обёрки чачакдор тарраби решаҳоро идора мекунад, агар хок хеле вазнин бошад, ҳамчунин хатари оббӯрии кам мавҷуд аст. Тавсия дода мешавад, ки пеш аз оғози фасл, беҳтар кардани сохтори хокро бо компост истифода баред. Инчунин, диққат ба pH ва сахтии оби обёркӣ барои пешгирии оморкунӣ дар чачакдорон муҳим аст. Мувофиати ионӣ дар ҳалли хӯрокворӣ, омили асосии нигоҳ доштани солимӣ ва ҷовононии ғалам аст.</p>\n\n<h2>Ҷавобҳо ба саволҳои муқаррарӣ (FAQ)</h2>\n<h3>Оё оби обёрки чачакдор барои сиёҳбӯда бо обёрки баронпаш фарқ мекунад?</h3>\n<p>Бале, чачакдор ҳароратро дар решаҳо нигоҳ медорад ва сабаби рушди ҳамвортар мешавад, дар ҳоле ки баронпаш метавонад боиси паҳн шудани спорҳои бемориҳо бар баргҳо шавад, ки барои сиёҳбӯда зарарнок аст.</p>\n<h3>Оё лентаҳои тампельӣ тақрибан мумкин аст?</h3>\n<p>Баъзе модели тампельҳо каппаи муқовимат ба UV доранд ва барои 1-2 мавсим истифода мешаванд, вале барои нигоҳ доштани сифати ҷараён, ивазкунии солӣ тавсия карда мешавад.</p>\n\n<h2>Хулоса</h2>\n<p>Истифодаи обёркунии тампельӣ ва лентаи тампельӣ дар кӯттои сир, тағйироти инқилобӣро дар идоракунии моҳалҳо ба вуҷуд меорад. Аз зиёд шудани истеҳсолот то кам шудани хароҷоти кор, ин системаҳо интихобек пахшиш ва иқтисодӣ мебошанд. Бо риояи принсибҳои нигоҳдорӣ, интихоби тампли мувофиқ ва татбиқи тақвимоти обёркунӣ, метавонед ба mahصولоти бо сифати барои экспорту пайо равед. Барои омӯзиши бештар дар бораи омили зиёдшавии истеҳсолот дар кӯттоҳои ноҳию сабзавот, метавонед ба мақолаҳои вобаста ба <a href="https://navar-abyari.ir/rye-harvest-per-hectare-factors-increase-yield/">зиёд шудани истеҳсоли раҷо дар гектар</a> ва муқоисаи он бо моҳалҳои сабз муроҷиат кунед. Мувоссиқи шумо дар моҳал, натиҷаи омехтаи дониши илмӣ бо дақиқии иҷроӣ аст.</p>','Машруҳи пурраи парҳез кардани сирбӯя бо обёрӣи қатраиҳо ва навони Tip','Сир яке аз бунёдҳои арзишманди кишоварӣ аст, ки бо идоракунии дурусти обварӣ метавонад ба меҳвари аъло расад. Дар ин дастрамбар мо принсипҳои ниҳории сир бо истифода аз технологияҳои навоварии обварии қатрагӣ ва нуритӣ-пайдарпайӣ-ро баррасӣ мекунем, то ҳам корфазл дар об дошта бошем ва ҳам ҳосилнокии деҳаи мо-ро зиёд кунем. Аз тайёрсозии хок то тақвими обварӣ ва идоракунии раъшкӣ, ҳама чиз дар як мақолаи мукаммал.','publish','closed','closed','mahshuri-karshidani-sirboya-bo-obariyi-quatariho-va-navoni-tip',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
