INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','راهنمای افزایش برداشت ذرت با سیستم آبیاری قطره‌ای قطبی برای کشاورزان عراقی' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','یادگیری بهترین روش‌های آبیاری قطره‌ای قطبی برای افزایش مقدار محصول ذرت در هکتار. راهنمای تخصصی و عملی برای بهینه‌سازی عملکرد کشاورزان با حفظ کیفیت و کاهش هزینه‌ها.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
